import heapq

def running_median(stream):
    low = []   # max-heap simulated with negated values
    high = []  # min-heap
    medians = []
    for num in stream:
        if not low or num <= -low[0]:
            heapq.heappush(low, -num)
        else:
            heapq.heappush(high, num)

        # Balance heaps so that len(low) >= len(high) and difference <= 1
        if len(low) > len(high) + 1:
            heapq.heappush(high, -heapq.heappop(low))
        elif len(high) > len(low):
            heapq.heappush(low, -heapq.heappop(high))

        # Compute median
        if len(low) > len(high):
            median = -low[0]
        else:
            median = (-low[0] + high[0]) / 2
        medians.append(median)
    return medians

print(running_median([5, 15, 1, 3]))

import heapq

class TaskQueue:
    def __init__(self):
        self._queue = []
        self._counter = 0

    def enqueue(self, priority, task):
        entry = (priority, self._counter, task)
        heapq.heappush(self._queue, entry)
        self._counter += 1

    def dequeue(self):
        if not self._queue:
            raise IndexError('dequeue from empty queue')
        return heapq.heappop(self._queue)[2]

if __name__ == '__main__':
    q = TaskQueue()
    q.enqueue(2, 'write_code')
    q.enqueue(1, 'debug')
    q.enqueue(1, 'review')
    print(q.dequeue())
    print(q.dequeue())

import heapq

def top_k_scores(scores, k):
    if k <= 0:
        return []
    k = min(k, len(scores))
    return sorted(heapq.nlargest(k, scores), reverse=True)

if __name__ == '__main__':
    data = [45, 12, 78, 33, 90, 56]
    print(top_k_scores(data, 3))

import heapq

def merge_k_sorted_lists(lists):
    result = []
    heap = []
    for idx, lst in enumerate(lists):
        if lst:
            heapq.heappush(heap, (lst[0], idx, 0))
    while heap:
        val, list_idx, elem_idx = heapq.heappop(heap)
        result.append(val)
        if elem_idx + 1 < len(lists[list_idx]):
            next_val = lists[list_idx][elem_idx + 1]
            heapq.heappush(heap, (next_val, list_idx, elem_idx + 1))
    return result

if __name__ == '__main__':
    input_lists = [[1, 4, 5], [1, 3, 4], [2, 6]]
    print(merge_k_sorted_lists(input_lists))

import heapq

class EmergencyTriage:
    def __init__(self):
        self._heap = []
        self._counter = 0

    def register_patient(self, priority, name):
        entry = (priority, self._counter, name)
        heapq.heappush(self._heap, entry)
        self._counter += 1

    def treat_next_patient(self):
        if not self._heap:
            raise IndexError('no patients to treat')
        return heapq.heappop(self._heap)[2]

